import React from "react";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";
import { useNavigate } from "react-router-dom";
import "../App.css";

const Dashboard = () => {
  const navigate = useNavigate();

  return (
    <div>
      <Navbar />

      <div className="dashboard-layout">
        {/* Sidebar Navigation */}
        <aside className="dashboard-sidebar">
          <h3>Quick Panel</h3>
          <button onClick={() => navigate("/create-listing")}>Create Listing</button>
          <button onClick={() => navigate("/view-listings")}>View Listings</button>
          <button onClick={() => navigate("/cart")}>Cart</button>
        </aside>

        {/* Main Content */}
        <main className="dashboard-main">
          {/* Top Right Buttons */}
          <div className="dashboard-topbar">
            <button onClick={() => navigate("/edit-profile")}>Edit Profile</button>
            <button onClick={() => navigate("/filter")}>Filter</button>
          </div>

          <h2>Welcome to Your Dashboard</h2>

          {/* Item Grid */}
          <div className="item-grid">
            {[1, 2, 3, 4, 5, 6].map((_, idx) => (
              <div className="item-card" key={idx}>
                <div className="image-placeholder">Image</div>
                <h4>Item Name</h4>
                <p>Description of the item goes here.</p>
                <p><strong>Condition:</strong> Like New</p>
                <p><strong>Price:</strong> $100</p>
                <div className="item-actions">
                  <button className="edit-btn">Edit</button>
                  <button className="buy-btn">Buy</button>
                </div>
              </div>
            ))}
          </div>
        </main>
      </div>

      <Footer />
    </div>
  );
};

export default Dashboard;
